-- Synthetic rollback-only Phase 4B volunteer authorization, isolation and integrity.
BEGIN;
CREATE TEMP TABLE phase4b_vol_assertions(label text primary key,category text not null) ON COMMIT DROP;
CREATE TEMP TABLE phase4b_vol_results(label text primary key,result jsonb not null) ON COMMIT DROP;
GRANT SELECT,INSERT,UPDATE ON pg_temp.phase4b_vol_assertions,pg_temp.phase4b_vol_results TO authenticated,anon;
CREATE FUNCTION pg_temp.f(label text) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$SELECT md5('boss-phase4b-volunteers:'||label)::uuid$$;
CREATE FUNCTION pg_temp.check(label text,category text,ok boolean) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL [%] %',category,label;END IF;INSERT INTO pg_temp.phase4b_vol_assertions VALUES(label,category);END$$;
CREATE FUNCTION pg_temp.act(label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claim','',true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.f('auth-'||label),'role','authenticated','is_anonymous',false,'session_id',pg_temp.f('session-'||label),'user_metadata',jsonb_build_object('role','platform_administrator'))::text,true);END$$;
CREATE FUNCTION pg_temp.cmd(op text,i jsonb) RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_build_object('operation',op,'input',i)$$;
CREATE FUNCTION pg_temp.ok(label text,cat text,c jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE r jsonb;BEGIN r:=public.boss_volunteers_mutate(pg_temp.f('request-'||label),c);PERFORM pg_temp.check(label,cat,r->>'request_id'=pg_temp.f('request-'||label)::text AND jsonb_typeof(r)='object');INSERT INTO pg_temp.phase4b_vol_results VALUES(label,r);RETURN r;END$$;
CREATE FUNCTION pg_temp.rid(label text) RETURNS uuid LANGUAGE sql AS $$SELECT (result->>'resource_id')::uuid FROM pg_temp.phase4b_vol_results WHERE phase4b_vol_results.label=$1$$;
CREATE FUNCTION pg_temp.deny(label text,cat text,c jsonb,states text[] DEFAULT ARRAY['PT403'],request_label text DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$DECLARE denied boolean:=false;BEGIN BEGIN PERFORM public.boss_volunteers_mutate(pg_temp.f('request-'||coalesce(request_label,label)),c);EXCEPTION WHEN OTHERS THEN IF SQLSTATE=ANY(states) THEN denied:=true;ELSE RAISE EXCEPTION 'FAIL % unexpected state %: %',label,SQLSTATE,SQLERRM;END IF;END;PERFORM pg_temp.check(label,cat,denied);END$$;
CREATE FUNCTION pg_temp.read_deny(label text,q jsonb) RETURNS void LANGUAGE plpgsql AS $$DECLARE denied boolean:=false;BEGIN BEGIN PERFORM public.boss_volunteers_read(q);EXCEPTION WHEN SQLSTATE 'PT403' THEN denied:=true;END;PERFORM pg_temp.check(label,'ISOLATION',denied);END$$;
CREATE FUNCTION pg_temp.query(label text DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_strip_nulls(jsonb_build_object('organization_id',pg_temp.f('org-a'),'shift_id',CASE WHEN label IS NOT NULL THEN pg_temp.rid(label) END))$$;
CREATE FUNCTION pg_temp.shift(label text,scope text DEFAULT 'team',target text DEFAULT 'team-a',cap integer DEFAULT 2,extra jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql AS $$SELECT pg_temp.cmd('shift.upsert',jsonb_build_object('organization_id',pg_temp.f('org-a'),'role_id',pg_temp.rid('role'),'title','Synthetic shift '||label,'scope_type',scope,'scope_id',pg_temp.f(target),'start_at',now()+interval '2 days','end_at',now()+interval '2 days 2 hours','capacity',cap,'status','open','visibility','members')||extra)$$;
CREATE FUNCTION pg_temp.edit(label text,changes jsonb) RETURNS jsonb LANGUAGE sql AS $$SELECT pg_temp.cmd('shift.upsert',(SELECT command->'input' FROM boss_private.volunteer_operation_receipts WHERE actor_person_id=pg_temp.f('admin') AND request_id=pg_temp.f('request-'||label))||jsonb_build_object('shift_id',pg_temp.rid(label),'expected_version',(SELECT version FROM public.volunteer_shifts WHERE id=pg_temp.rid(label)))||changes)$$;
-- Test-only edit helper reads fixture state as owner, never exposed outside temp schema.
ALTER FUNCTION pg_temp.edit(text,jsonb) SECURITY DEFINER;
DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure f FROM pg_proc p WHERE p.pronamespace=pg_my_temp_schema() LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.f);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,anon',f.f);END LOOP;END$$;
DO $$DECLARE t text;f record;BEGIN
 FOREACH t IN ARRAY ARRAY['volunteer_role_definitions','volunteer_shifts','volunteer_assignments','volunteer_assignment_history'] LOOP
 PERFORM pg_temp.check(t||' RLS','SECURITY',(SELECT relrowsecurity FROM pg_class WHERE oid=('public.'||t)::regclass));
 PERFORM pg_temp.check(t||' authenticated rawclosed','SECURITY',NOT has_table_privilege('authenticated','public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'));
 PERFORM pg_temp.check(t||' anon rawclosed','SECURITY',NOT has_table_privilege('anon','public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'));
 PERFORM pg_temp.check(t||' service rawclosed','SECURITY',NOT has_table_privilege('service_role','public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'));END LOOP;
 FOR f IN SELECT p.oid::regprocedure id,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='boss_private' AND p.proname IN('volunteer_permission','volunteer_person_eligible','volunteer_guardian','volunteer_can_view_shift','volunteer_notification_recipient','volunteer_command') LOOP PERFORM pg_temp.check(f.proname||' privateclosed','SECURITY',NOT has_function_privilege('authenticated',f.id,'EXECUTE') AND NOT has_function_privilege('anon',f.id,'EXECUTE'));END LOOP;
 PERFORM pg_temp.check('public invoker wrappers','SECURITY',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'boss_volunteers_%' AND p.prosecdef));
 PERFORM pg_temp.check('anon RPCclosed','SECURITY',NOT has_function_privilege('anon','public.boss_volunteers_read(jsonb)','EXECUTE') AND NOT has_function_privilege('anon','public.boss_volunteers_mutate(uuid,jsonb)','EXECUTE'));
END$$;
INSERT INTO auth.users(id,email,email_confirmed_at) SELECT pg_temp.f('auth-'||p),p||'@phase4b-volunteers.example.invalid',now()-interval '1 day' FROM unnest(ARRAY['platform','admin','admin-b','coach','assistant','coordinator','unit','parent','parent2','household','expired-guardian','outsider','minor','unknown','expired-role'])p;
INSERT INTO auth.sessions(id,user_id) SELECT pg_temp.f('session-'||p),pg_temp.f('auth-'||p) FROM unnest(ARRAY['platform','admin','admin-b','coach','assistant','coordinator','unit','parent','parent2','household','expired-guardian','outsider','minor','unknown','expired-role'])p;
INSERT INTO public.people(id,display_name,date_of_birth) SELECT pg_temp.f(p),'Synthetic volunteer '||p,CASE WHEN p IN('child','child2','minor') THEN current_date-interval '12 years' WHEN p='unknown' THEN NULL ELSE date '1980-01-01' END FROM unnest(ARRAY['platform','admin','admin-b','coach','assistant','coordinator','unit','parent','parent2','household','expired-guardian','outsider','minor','unknown','expired-role','child','child2'])p;
INSERT INTO public.user_accounts(auth_user_id,person_id,account_status) SELECT pg_temp.f('auth-'||p),pg_temp.f(p),'active' FROM unnest(ARRAY['platform','admin','admin-b','coach','assistant','coordinator','unit','parent','parent2','household','expired-guardian','outsider','minor','unknown','expired-role'])p;
INSERT INTO public.organizations(id,name,slug) VALUES(pg_temp.f('org-a'),'Synthetic volunteer A','phase4b-vol-a'),(pg_temp.f('org-b'),'Synthetic volunteer B','phase4b-vol-b');
INSERT INTO public.organization_units(id,organization_id,name,slug,unit_type,parent_unit_id) VALUES(pg_temp.f('unit-a'),pg_temp.f('org-a'),'Synthetic volunteer unit','unit-a','sport',NULL),(pg_temp.f('unit-sibling'),pg_temp.f('org-a'),'Synthetic sibling','unit-sibling','sport',NULL),(pg_temp.f('unit-descendant'),pg_temp.f('org-a'),'Synthetic descendant','unit-descendant','program',pg_temp.f('unit-a'));
INSERT INTO public.teams(id,organization_id,parent_unit_id,name,slug) VALUES(pg_temp.f('team-a'),pg_temp.f('org-a'),pg_temp.f('unit-a'),'Synthetic Falcons','falcons'),(pg_temp.f('team-b'),pg_temp.f('org-a'),pg_temp.f('unit-sibling'),'Synthetic Tigers','tigers'),(pg_temp.f('team-child'),pg_temp.f('org-a'),pg_temp.f('unit-descendant'),'Synthetic descendant','descendant'),(pg_temp.f('team-other'),pg_temp.f('org-b'),NULL,'Synthetic other','other');
UPDATE public.teams SET status='active' WHERE organization_id IN(pg_temp.f('org-a'),pg_temp.f('org-b'));
INSERT INTO public.organization_modules(organization_id,module_id,status,starts_at,configuration) SELECT pg_temp.f(org),m.id,'active',now()-interval '1 day',CASE WHEN m.key='volunteers' THEN '{"volunteers":true,"self_signup":true,"reminders":true,"head_coach_management":false,"assistant_management":false,"minimum_signup_age":18}'::jsonb ELSE '{}'::jsonb END FROM public.modules m CROSS JOIN unnest(ARRAY['org-a','org-b'])org WHERE m.key IN('calendar','volunteers');
INSERT INTO public.role_assignments(person_id,role_id,scope_type,scope_id,organization_id,starts_at,ends_at) SELECT pg_temp.f(p),r.id,scope,CASE WHEN target IS NOT NULL THEN pg_temp.f(target) END,CASE WHEN org IS NOT NULL THEN pg_temp.f(org) END,now()-interval '2 days',CASE WHEN p='expired-role' THEN now()-interval '1 day' END FROM(VALUES('platform','platform_administrator','platform',NULL,NULL),('admin','organization_administrator','organization','org-a','org-a'),('admin-b','organization_administrator','organization','org-b','org-b'),('coach','head_coach','team','team-a','org-a'),('assistant','assistant_coach','team','team-a','org-a'),('coordinator','volunteer_coordinator','team','team-a','org-a'),('unit','program_administrator','organization_unit','unit-a','org-a'),('expired-role','volunteer_coordinator','team','team-a','org-a'))v(p,role,scope,target,org) JOIN public.roles r ON r.key=v.role;
INSERT INTO public.organization_memberships(organization_id,person_id,starts_at) SELECT pg_temp.f('org-a'),pg_temp.f(p),now()-interval '1 day' FROM unnest(ARRAY['admin','coach','assistant','coordinator','unit','minor','unknown','child','child2','expired-role'])p;
