INSERT INTO public.participants(id,person_id,participant_type) VALUES(pg_temp.f('participant'),pg_temp.f('child'),'athlete'),(pg_temp.f('participant2'),pg_temp.f('child2'),'athlete');
INSERT INTO public.team_memberships(organization_id,team_id,person_id,participant_id,membership_type,starts_at) VALUES(pg_temp.f('org-a'),pg_temp.f('team-a'),pg_temp.f('child'),pg_temp.f('participant'),'athlete',now()-interval '1 day'),(pg_temp.f('org-a'),pg_temp.f('team-b'),pg_temp.f('child2'),pg_temp.f('participant2'),'athlete',now()-interval '1 day');
INSERT INTO public.team_memberships(organization_id,team_id,person_id,membership_type,starts_at) SELECT pg_temp.f('org-a'),pg_temp.f('team-a'),pg_temp.f(p),'staff',now()-interval '1 day' FROM unnest(ARRAY['coach','assistant','coordinator','expired-role','minor','unknown'])p;
