INSERT INTO public.households(id,name) VALUES(pg_temp.f('household'),'Synthetic volunteer household');
INSERT INTO public.household_memberships(household_id,person_id,starts_at) SELECT pg_temp.f('household'),pg_temp.f(p),now()-interval '1 day' FROM unnest(ARRAY['parent','child','household'])p;
-- Canonical Calendar occurrence identity requires whole-second event times.
INSERT INTO public.events(id,organization_id,title,event_type_key,start_at,end_at,timezone,status,visibility,created_by_person_id,updated_by_person_id,recurrence) VALUES(pg_temp.f('event'),pg_temp.f('org-a'),'Synthetic volunteer event','practice',date_trunc('second',now())+interval '2 days',date_trunc('second',now())+interval '2 days 2 hours','UTC','scheduled','member',pg_temp.f('admin'),pg_temp.f('admin'),NULL),(pg_temp.f('recurring-event'),pg_temp.f('org-a'),'Synthetic recurring event','practice',date_trunc('second',now())+interval '3 days',date_trunc('second',now())+interval '3 days 2 hours','UTC','scheduled','member',pg_temp.f('admin'),pg_temp.f('admin'),'{"frequency":"daily","count":3}');
INSERT INTO public.event_targets(event_id,organization_id,target_type,target_id) VALUES(pg_temp.f('event'),pg_temp.f('org-a'),'team',pg_temp.f('team-a')),(pg_temp.f('recurring-event'),pg_temp.f('org-a'),'team',pg_temp.f('team-a'));
SET LOCAL ROLE authenticated;SELECT pg_temp.act('admin');
SELECT pg_temp.ok('role','A',pg_temp.cmd('role.upsert',jsonb_build_object('organization_id',pg_temp.f('org-a'),'name','Synthetic concessions','description','Synthetic configurable duty')));
SELECT pg_temp.ok('event-shift','A',pg_temp.shift('event','team','team-a',2,jsonb_build_object('event_id',pg_temp.f('event'))));
SELECT pg_temp.ok('open-shift','A',pg_temp.shift('open'));
SELECT pg_temp.ok('sibling-shift','A',pg_temp.shift('sibling','team','team-b'));
SELECT pg_temp.ok('unit-shift','A',pg_temp.shift('unit','unit','unit-a'));
SELECT pg_temp.ok('descendant-shift','A',pg_temp.shift('descendant','team','team-child'));
SELECT pg_temp.ok('staff-shift','A',pg_temp.shift('staff','team','team-a',2,'{"visibility":"staff"}'));
SELECT pg_temp.ok('deadline-shift','DEADLINE',pg_temp.shift('deadline','team','team-a',2,jsonb_build_object('signup_deadline',now()-interval '1 hour')));
SELECT pg_temp.check('read operations retain finite staff and own actions','PROJECTION',public.boss_volunteers_read(pg_temp.query())->'operations'@>'["role.upsert","volunteers.configure","shift.upsert","reminders.prepare","assignment.signup","assignment.cancel"]'::jsonb);
SELECT pg_temp.deny('forged team in other organization','ISOLATION',pg_temp.shift('forged','team','team-other'));
SELECT pg_temp.deny('forged event occurrence','OCCURRENCE',pg_temp.shift('forged-key','team','team-a',2,jsonb_build_object('event_id',pg_temp.f('event'),'occurrence_key','2000-01-01T00:00:00')));
SELECT pg_temp.deny('sibling event target mismatches shift','OCCURRENCE',pg_temp.shift('wrong-target','team','team-b',2,jsonb_build_object('event_id',pg_temp.f('event'))));
SELECT pg_temp.deny('occurrence without event','OCCURRENCE',pg_temp.shift('key-only','team','team-a',2,'{"occurrence_key":"2000-01-01T00:00:00"}'),ARRAY['PT422']);
SELECT pg_temp.deny('recurrence requires specific occurrence','OCCURRENCE',pg_temp.shift('series','team','team-a',2,jsonb_build_object('event_id',pg_temp.f('recurring-event'))));
SELECT pg_temp.ok('recurring-shift-1','OCCURRENCE',pg_temp.shift('series-first','team','team-a',2,jsonb_build_object('event_id',pg_temp.f('recurring-event'),'occurrence_key',to_char((date_trunc('second',now())+interval '3 days') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))));
SELECT pg_temp.ok('recurring-shift-2','OCCURRENCE',pg_temp.shift('series-second','team','team-a',2,jsonb_build_object('event_id',pg_temp.f('recurring-event'),'occurrence_key',to_char((date_trunc('second',now())+interval '4 days') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))));
SELECT pg_temp.check('recurring shifts retain separate occurrence identity','OCCURRENCE',public.boss_volunteers_read(pg_temp.query('recurring-shift-1'))->'detail'->>'occurrence_key'<>public.boss_volunteers_read(pg_temp.query('recurring-shift-2'))->'detail'->>'occurrence_key');
SELECT pg_temp.deny('unsafe capacity override field','CAPACITY',pg_temp.shift('override','team','team-a',2,'{"override_capacity":true}'),ARRAY['PT422']);
SELECT pg_temp.deny('unbounded reminder window rejected','REMINDER',pg_temp.cmd('reminders.prepare',jsonb_build_object('organization_id',pg_temp.f('org-a'),'window_start',now(),'window_end',now()+interval '8 days')),ARRAY['PT422']);
SELECT pg_temp.deny('minimum age cannot enable minors','MINOR',pg_temp.cmd('volunteers.configure',jsonb_build_object('organization_id',pg_temp.f('org-a'),'configuration','{"minimum_signup_age":12}'::jsonb)),ARRAY['PT422']);
SELECT pg_temp.deny('malformed minimum age rejected','MINOR',pg_temp.cmd('volunteers.configure',jsonb_build_object('organization_id',pg_temp.f('org-a'),'configuration','{"minimum_signup_age":null}'::jsonb)),ARRAY['PT422']);
SELECT pg_temp.act('parent');
SELECT pg_temp.ok('parent-signup','B',pg_temp.cmd('assignment.signup',jsonb_build_object('shift_id',pg_temp.rid('open-shift'))));
SELECT pg_temp.check('own commitment family projection','M',jsonb_array_length(public.boss_volunteers_read(pg_temp.query()||'{"view":"family"}')->'commitments')=1);
SELECT pg_temp.check('family commitment preserves exact team label','M',public.boss_volunteers_read(pg_temp.query()||'{"view":"family"}')->'commitments'->0->>'scope_label'='Synthetic Falcons');
SELECT pg_temp.check('guardian not given otherperson roster','ISOLATION',NOT public.boss_volunteers_read(pg_temp.query('open-shift'))::text LIKE '%assignments%');
SELECT pg_temp.check('filled and unfilled summary','L',(public.boss_volunteers_read(pg_temp.query('open-shift'))->'detail'->>'filled')::integer=1 AND(public.boss_volunteers_read(pg_temp.query('open-shift'))->'detail'->>'unfilled')::integer=1);
DO $$DECLARE r jsonb;BEGIN r:=public.boss_volunteers_mutate(pg_temp.f('request-parent-signup'),pg_temp.cmd('assignment.signup',jsonb_build_object('shift_id',pg_temp.rid('open-shift'))));PERFORM pg_temp.check('exact retry same commitment','D',r->>'resource_id'=pg_temp.rid('parent-signup')::text);END$$;
SELECT pg_temp.ok('parent-fresh-retry','D',pg_temp.cmd('assignment.signup',jsonb_build_object('shift_id',pg_temp.rid('open-shift'))));
SELECT pg_temp.check('fresh duplicate same resource','D',pg_temp.rid('parent-fresh-retry')=pg_temp.rid('parent-signup'));
SELECT pg_temp.deny('self cannot inject another person','OWNERSHIP',pg_temp.cmd('assignment.signup',jsonb_build_object('shift_id',pg_temp.rid('open-shift'),'person_id',pg_temp.f('parent2'))),ARRAY['PT422']);
SELECT pg_temp.deny('parent cannot assign another','G',pg_temp.cmd('assignment.assign',jsonb_build_object('shift_id',pg_temp.rid('open-shift'),'person_id',pg_temp.f('parent2'))));
