SELECT pg_temp.act('admin');
SELECT pg_temp.ok('assign-parent2','G',pg_temp.cmd('assignment.assign',jsonb_build_object('shift_id',pg_temp.rid('open-shift'),'person_id',pg_temp.f('parent2'))));
